// Score is calculated in the source match's chronological order, never playback order.
function key(name){let n=(name||'').toLowerCase();for(let x of ['fischer','spassky','carlsen','anand','karjakin','caruana','nepomniachtchi','gukesh'])if(n.includes(x))return x;if(n.includes('ding')||n.includes('liren'))return 'ding';return n.trim()}
function add(score,game){let w=key(game.tags.White),b=key(game.tags.Black),r=game.tags.Result;if(r==='1-0'){score[w]=(score[w]||0)+1}else if(r==='0-1'){score[b]=(score[b]||0)+1}else if(r==='1/2-1/2'){score[w]=(score[w]||0)+.5;score[b]=(score[b]||0)+.5}}
export function attachMatchScores(games,matchId){if(!games.length)return;let classical={},rapid={};for(const [i,g] of games.entries()){if(matchId==='fischer'&&Number(g.tags.Round)>=3&&i===1)classical.spassky=(classical.spassky||0)+1;const before={classical:{...classical},rapid:{...rapid}};const tie=/rapid|blitz/i.test(g.tags.EventType||'');add(tie?rapid:classical,g);g.matchScore={before,after:{classical:{...classical},rapid:{...rapid}},tie};}}
function number(n){return n%1?`${Math.floor(n)?Math.floor(n):''}½`:String(n)}
export function scoreFor(game,after){if(!game.matchScore)return null;let score=game.matchScore[after?'after':'before'];let w=key(game.tags.White),b=key(game.tags.Black);let pair=map=>`${number(map[w]||0)} – ${number(map[b]||0)}`;return {main:pair(score.classical),tie:game.matchScore.tie?pair(score.rapid):null,finished:after}}
